
/**
 * Beatstar 120 FPS High-Performance Canvas Rhythm Engine
 * High-Fidelity Audio Samples (Base64 WAV), 2.0s Rewind Duration,
 * Complete Note Clearance (Up to Fail + 1.0s Future Clearance) & Anti-Double-Miss Guard
 */

const SFX_MISS_BASE64 = 'data:audio/wav;base64,';
const SFX_SCRATCH_BASE64 = 'data:audio/wav;base64,';


class HighFidelityAudioPlayer {
  constructor() {
    this.missAudio = new Audio(SFX_MISS_BASE64);
    this.missAudio.volume = 0.85;

    this.scratchAudio = new Audio(SFX_SCRATCH_BASE64);
    this.scratchAudio.volume = 0.88;

    this.audioCtx = null;
  }

  ensureContext() {
    if (!this.audioCtx) {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      this.audioCtx = new AudioContextClass();
    }
    if (this.audioCtx.state === 'suspended') {
      this.audioCtx.resume();
    }
    return this.audioCtx;
  }

  // 1. High-Fidelity Metallic Punchy Arcade Error Sample
  playPunchyArcadeMiss() {
    try {
      const snd = this.missAudio.cloneNode();
      snd.volume = 0.85;
      snd.currentTime = 0;
      snd.play().catch(() => {});
    } catch (e) {}
  }

  // 2. High-Fidelity Vinyl Backspin / Tape Rewind Sample
  playAnalogTapeRewind() {
    try {
      const snd = this.scratchAudio.cloneNode();
      snd.volume = 0.88;
      snd.currentTime = 0;
      snd.play().catch(() => {});
    } catch (e) {}
  }

  playPianoChime(scheduledTime = null, freq = 523.25) {
    const ctx = this.ensureContext();
    const startTime = scheduledTime !== null ? scheduledTime : ctx.currentTime;

    const osc1 = ctx.createOscillator();
    const osc2 = ctx.createOscillator();
    const gain = ctx.createGain();

    osc1.type = 'triangle';
    osc1.frequency.setValueAtTime(freq, startTime);

    osc2.type = 'sine';
    osc2.frequency.setValueAtTime(freq * 2, startTime);

    gain.gain.setValueAtTime(0.0001, startTime);
    gain.gain.exponentialRampToValueAtTime(0.45, startTime + 0.006);
    gain.gain.exponentialRampToValueAtTime(0.0001, startTime + 0.35);

    osc1.connect(gain);
    osc2.connect(gain);
    gain.connect(ctx.destination);

    osc1.start(startTime);
    osc2.start(startTime);
    osc1.stop(startTime + 0.38);
    osc2.stop(startTime + 0.38);
  }

  playClick(scheduledTime = null) {
    const ctx = this.ensureContext();
    const startTime = scheduledTime !== null ? scheduledTime : ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(880, startTime);
    gain.gain.setValueAtTime(0.25, startTime);
    gain.gain.exponentialRampToValueAtTime(0.001, startTime + 0.04);

    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(startTime);
    osc.stop(startTime + 0.05);
  }
}

class YouTubeSync {
  constructor(onReady, onStateChange, onError) {
    this.player = null;
    this.isReady = false;
    this.isPlaying = false;
    
    this.baseTimeMs = 0;
    this.basePerfNow = 0;
    this.lastPollPerfTime = 0;
    
    this.onReady = onReady;
    this.onStateChange = onStateChange;
    this.onError = onError;
    this.watchdogTimer = null;
    this.initApi();
  }

  initApi() {
    if (window.YT && window.YT.Player) {
      this.createPlayer();
    } else {
      const tag = document.createElement('script');
      tag.src = "https://www.youtube.com/iframe_api";
      const firstScriptTag = document.getElementsByTagName('script')[0];
      firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);
      window.onYouTubeIframeAPIReady = () => this.createPlayer();
    }
  }

  createPlayer() {
    this.player = new YT.Player('ytPlayer', {
      height: '100%',
      width: '100%',
      videoId: 'kJQP7kiw5Fk',
      playerVars: {
        autoplay: 0,
        controls: 0,
        disablekb: 1,
        enablejsapi: 1,
        fs: 0,
        iv_load_policy: 3,
        modestbranding: 1,
        playsinline: 1,
        rel: 0,
        showinfo: 0,
        autohide: 1,
        origin: window.location.origin
      },
      events: {
        onReady: () => {
          this.isReady = true;
          if (this.onReady) this.onReady();
        },
        onStateChange: (event) => {
          if (event.data === YT.PlayerState.PLAYING) {
            this.clearWatchdog();
            this.isPlaying = true;
            try {
              const cur = this.player.getCurrentTime();
              if (typeof cur === 'number' && !isNaN(cur) && cur > 0) {
                this.baseTimeMs = cur * 1000;
              }
            } catch (e) {}
            this.basePerfNow = performance.now();
            this.lastPollPerfTime = this.basePerfNow;
          } else {
            this.isPlaying = false;
          }
          if (this.onStateChange) this.onStateChange(event.data);
        },
        onError: (event) => {
          this.clearWatchdog();
          this.handlePlayerError(event.data);
        }
      }
    });
  }

  handlePlayerError(errorCode) {
    let msg = "Error al reproducir el vídeo de YouTube.";
    if (errorCode === 101 || errorCode === 150) {
      msg = "Este vídeo no permite reproducción externa por restricciones de derechos de autor. Selecciona otra versión o canción.";
    } else if (errorCode === 100) {
      msg = "El vídeo no existe o ha sido marcado como privado/eliminado.";
    } else if (errorCode === 2 || errorCode === 5) {
      msg = "Parámetro o reproductor HTML5 no válido. Intenta con otra canción.";
    }

    if (this.onError) {
      this.onError(errorCode, msg);
    }
  }

  startWatchdog(timeoutMs = 15000) {
    this.clearWatchdog();
    this.watchdogTimer = setTimeout(() => {
      if (!this.isPlaying) {
        this.handlePlayerError(504);
      }
    }, timeoutMs);
  }

  clearWatchdog() {
    if (this.watchdogTimer) {
      clearTimeout(this.watchdogTimer);
      this.watchdogTimer = null;
    }
  }

  loadVideo(videoId) {
    if (!this.player || !this.isReady) return;
    this.startWatchdog(15000);
    this.player.loadVideoById({
      videoId: videoId,
      startSeconds: 0
    });
    this.baseTimeMs = 0;
    this.basePerfNow = performance.now();
  }

  play() {
    this.isPlaying = true;
    if (this.player && this.isReady) {
      try {
        this.player.playVideo();
      } catch (e) {}
    }
  }

  pause() {
    this.clearWatchdog();
    if (this.player && this.isReady) {
      try {
        this.player.pauseVideo();
      } catch (e) {}
    }
    this.isPlaying = false;
  }

  seekTo(seconds) {
    this.baseTimeMs = seconds * 1000;
    this.basePerfNow = performance.now();
    this.lastPollPerfTime = this.basePerfNow;
    this.isPlaying = true;
    if (this.player && this.isReady) {
      try {
        this.player.seekTo(seconds, true);
      } catch (e) {}
    }
  }

  getCurrentTimeMs() {
    if (!this.player || !this.isReady) return this.baseTimeMs;
    const now = performance.now();

    if (!this.isPlaying) {
      return this.baseTimeMs;
    }

    if (now - this.lastPollPerfTime > 300) {
      this.lastPollPerfTime = now;
      try {
        if (typeof this.player.getCurrentTime === 'function') {
          const actualSec = this.player.getCurrentTime();
          if (typeof actualSec === 'number' && !isNaN(actualSec) && actualSec > 0) {
            const actualMs = actualSec * 1000;
            const currentInterp = this.baseTimeMs + (now - this.basePerfNow);
            const drift = actualMs - currentInterp;

            if (Math.abs(drift) > 50 && actualMs > (this.baseTimeMs - 2000)) {
              this.baseTimeMs = actualMs;
              this.basePerfNow = now;
            } else if (Math.abs(drift) > 15) {
              this.baseTimeMs += drift * 0.3;
            }
          }
        }
      } catch (e) {}
    }

    return this.baseTimeMs + (now - this.basePerfNow);
  }
}

class ParticleSystem {
  constructor() {
    this.particles = [];
    this.shockwaves = [];
  }

  emitHit(x, y, color = '#00f2fe', count = 24) {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 260 + 80;
      this.particles.push({
        x: x,
        y: y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 50,
        size: Math.random() * 5 + 3,
        color: color,
        alpha: 1.0,
        decay: Math.random() * 2.0 + 1.8,
        gravity: 360
      });
    }

    this.shockwaves.push({
      x: x,
      y: y,
      radius: 8,
      maxRadius: 75,
      color: color,
      alpha: 0.9,
      speed: 280
    });
  }

  emitSwipeBurst(x, y, direction = 'up', color = '#fee140', count = 36) {
    let baseAngle = -Math.PI / 2;
    if (direction === 'down') baseAngle = Math.PI / 2;
    if (direction === 'left') baseAngle = Math.PI;
    if (direction === 'right') baseAngle = 0;

    for (let i = 0; i < count; i++) {
      const spread = (Math.random() - 0.5) * 1.5;
      const angle = baseAngle + spread;
      const speed = Math.random() * 420 + 160;
      this.particles.push({
        x: x,
        y: y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        size: Math.random() * 7 + 3,
        color: color,
        alpha: 1.0,
        decay: Math.random() * 2.2 + 2.0,
        gravity: 120
      });
    }

    this.shockwaves.push({
      x: x,
      y: y,
      radius: 16,
      maxRadius: 120,
      color: color,
      alpha: 1.0,
      speed: 380
    });
  }

  emitHoldSpark(x, y, color = '#00ff88') {
    for (let i = 0; i < 4; i++) {
      const angle = (Math.random() - 0.5) * Math.PI;
      const speed = Math.random() * 160 + 60;
      this.particles.push({
        x: x + (Math.random() - 0.5) * 32,
        y: y,
        vx: Math.cos(angle) * speed,
        vy: -Math.abs(Math.sin(angle)) * speed,
        size: Math.random() * 5 + 2,
        color: color,
        alpha: 0.95,
        decay: 3.2,
        gravity: 160
      });
    }
  }

  update(dt) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += p.gravity * dt;
      p.alpha -= p.decay * dt;
      p.size = Math.max(0, p.size - dt * 2.5);

      if (p.alpha <= 0 || p.size <= 0) {
        this.particles.splice(i, 1);
      }
    }

    for (let i = this.shockwaves.length - 1; i >= 0; i--) {
      const sw = this.shockwaves[i];
      sw.radius += sw.speed * dt;
      sw.alpha -= dt * 2.5;

      if (sw.alpha <= 0 || sw.radius >= sw.maxRadius) {
        this.shockwaves.splice(i, 1);
      }
    }
  }

  render(ctx) {
    ctx.save();
    for (const sw of this.shockwaves) {
      ctx.beginPath();
      ctx.arc(sw.x, sw.y, sw.radius, 0, Math.PI * 2);
      ctx.strokeStyle = sw.color;
      ctx.lineWidth = 4.0;
      ctx.globalAlpha = Math.max(0, sw.alpha);
      ctx.stroke();
    }

    ctx.globalCompositeOperation = 'lighter';
    for (const p of this.particles) {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      ctx.fillStyle = p.color;
      ctx.globalAlpha = Math.max(0, p.alpha);
      ctx.fill();
    }
    ctx.restore();
  }
}

class BeatstarEngine {
  constructor(canvas, uiCallbacks) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: true });
    this.ui = uiCallbacks;

    this.dpr = window.devicePixelRatio || 1;
    this.width = 0;
    this.height = 0;
    this.laneWidth = 0;
    this.hitLineY = 0;
    this.scrollDurationMs = 1400;

    this.notes = [];
    this.activeHolds = new Map();
    this.activeTouches = new Map();
    this.laneGlows = [0, 0, 0];
    
    // Scoring & Multiplier System
    this.score = 0;
    this.combo = 0;
    this.maxCombo = 0;
    this.streakCount = 0;
    this.multiplier = 1;
    this.stars = 0;
    this.targetScore = 100000;
    this.missCount = 0;
    this.invulnerableUntil = 0;
    this.isInitialLaunch = true;
    this.isRewinding = false;
    this.judgements = [];
    this.stats = { perfectPlus: 0, perfect: 0, great: 0, miss: 0 };

    // Anti-Double-Miss Protection & Cooldown
    this.lastMissTimePerf = 0;
    this.isProcessingMiss = false;
    this.lastFailSongTimeSec = 0;

    this.latencyOffsetMs = parseInt(localStorage.getItem('beatstar_offset') || '0', 10);
    this.continueMode = localStorage.getItem('beatstar_continue_mode') === 'true';
    this.isRunning = false;
    this.isPaused = false;
    this.isGameOver = false;
    this.animFrameId = null;

    // Pure Visual Calibration State
    this.isCalibrating = false;
    this.calibrationStartTime = 0;
    this.calibrationIntervalMs = 2000;
    this.nextCalibNoteTime = 0;
    this.synth = new HighFidelityAudioPlayer();

    this.particles = new ParticleSystem();
    this.sync = new YouTubeSync(
      () => this.onPlayerReady(),
      (state) => this.onPlayerStateChange(state),
      (code, msg) => this.onPlayerError(code, msg)
    );

    this.initCanvasSize();
    this.bindEvents();
  }

  setLatencyOffset(offsetMs) {
    this.latencyOffsetMs = parseInt(offsetMs, 10) || 0;
    localStorage.setItem('beatstar_offset', this.latencyOffsetMs.toString());
  }

  setContinueMode(enabled) {
    this.continueMode = !!enabled;
    localStorage.setItem('beatstar_continue_mode', this.continueMode.toString());
  }

  initCanvasSize() {
    const rect = this.canvas.getBoundingClientRect();
    this.width = rect.width;
    this.height = rect.height;
    this.laneWidth = this.width / 3;
    this.hitLineY = this.height * 0.82;

    this.canvas.width = this.width * this.dpr;
    this.canvas.height = this.height * this.dpr;
    this.ctx.scale(this.dpr, this.dpr);
  }

  bindEvents() {
    window.addEventListener('resize', () => this.initCanvasSize());

    this.canvas.addEventListener('touchstart', (e) => this.handleTouchStart(e), { passive: false });
    this.canvas.addEventListener('touchmove', (e) => this.handleTouchMove(e), { passive: false });
    this.canvas.addEventListener('touchend', (e) => this.handleTouchEnd(e), { passive: false });
    this.canvas.addEventListener('touchcancel', (e) => this.handleTouchEnd(e), { passive: false });

    this.canvas.addEventListener('mousedown', (e) => this.handleMouseDown(e));
    this.canvas.addEventListener('mousemove', (e) => this.handleMouseMove(e));
    this.canvas.addEventListener('mouseup', (e) => this.handleMouseUp(e));

    window.addEventListener('keydown', (e) => {
      if (e.repeat) return;
      if (e.key === 'Escape' || e.key === 'p' || e.key === 'P') {
        if (!this.isCalibrating && this.beatmapData) {
          if (this.isPaused) {
            if (this.ui.onResume) this.ui.onResume();
          } else {
            if (this.ui.onTogglePause) this.ui.onTogglePause();
          }
          return;
        }
      }
      if (this.isPaused || this.isRewinding) return;

      if (e.key === 'a' || e.key === 'A') this.triggerLaneInput(0, 'tap');
      if (e.key === 's' || e.key === 'S' || e.key === ' ') this.triggerLaneInput(1, 'tap');
      if (e.key === 'd' || e.key === 'D') this.triggerLaneInput(2, 'tap');
      if (e.key === 'ArrowLeft') this.triggerLaneInput(0, 'swipe', 'left');
      if (e.key === 'ArrowRight') this.triggerLaneInput(2, 'swipe', 'right');
      if (e.key === 'ArrowUp') this.triggerLaneInput(1, 'swipe', 'up');
      if (e.key === 'ArrowDown') this.triggerLaneInput(1, 'swipe', 'down');
    });

    window.addEventListener('keyup', (e) => {
      if (this.isPaused || this.isRewinding) return;
      if (e.key === 'a' || e.key === 'A') this.releaseLaneHold(0);
      if (e.key === 's' || e.key === 'S' || e.key === ' ') this.releaseLaneHold(1);
      if (e.key === 'd' || e.key === 'D') this.releaseLaneHold(2);
    });
  }

  loadBeatmap(beatmapData) {
    this.isCalibrating = false;
    this.beatmapData = beatmapData;
    this.isInitialLaunch = true;
    this.isRewinding = false;
    this.isProcessingMiss = false;
    this.lastMissTimePerf = 0;
    this.lastFailSongTimeSec = 0;
    
    let baseScroll = 1400;
    if (beatmapData.metadata && beatmapData.metadata.scroll_duration_ms) {
      baseScroll = beatmapData.metadata.scroll_duration_ms;
    } else {
      const diff = beatmapData.metadata?.difficulty || 'normal';
      if (diff === 'easy') baseScroll = 1800;
      else if (diff === 'normal') baseScroll = 1400;
      else if (diff === 'hard') baseScroll = 950;
      else baseScroll = 800;
    }

    this.scrollDurationMs = baseScroll;

    this.notes = beatmapData.notes.map(n => ({
      ...n,
      hit: false,
      holding: false,
      holdCompleted: false,
      missed: false,
      processed: false
    }));

    this.activeHolds.clear();
    this.activeTouches.clear();
    this.score = 0;
    this.combo = 0;
    this.maxCombo = 0;
    this.streakCount = 0;
    this.multiplier = 1;
    this.stars = 0;
    this.missCount = 0;
    this.invulnerableUntil = 0;
    this.stats = { perfectPlus: 0, perfect: 0, great: 0, miss: 0 };
    
    this.targetScore = Math.max(20000, this.notes.length * 450 * 3.5);
    this.isGameOver = false;
    this.isPaused = false;

    this.sync.loadVideo(beatmapData.video_id);
    this.ui.onScoreUpdate(this.score, this.combo, this.stars, this.multiplier);
    this.ui.onSongLoaded(beatmapData.metadata);
    this.startLoop();
  }

  startNativeCalibration() {
    this.isCalibrating = true;
    this.scrollDurationMs = 1400;
    this.isPaused = false;
    this.isGameOver = false;
    this.isRewinding = false;
    this.sync.pause();
    this.notes = [];
    this.activeHolds.clear();
    this.activeTouches.clear();
    this.judgements = [];

    this.synth.ensureContext();
    this.calibrationStartTime = performance.now();
    this.nextCalibNoteTime = this.calibrationStartTime + 400;
    this.startLoop();
  }

  stopNativeCalibration() {
    this.isCalibrating = false;
    this.notes = [];
    this.activeHolds.clear();
    this.judgements = [];
    this.stop();
  }

  pause() {
    this.isPaused = true;
    this.sync.pause();
    if (this.animFrameId) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }
  }

  resume() {
    this.isPaused = false;
    this.isRewinding = false;
    this.isProcessingMiss = false;
    this.lastMissTimePerf = performance.now();
    this.sync.play();
    if (!this.animFrameId) {
      this.startLoop();
    }
  }

  /**
   * Smooth Visual Rewind Animation (600ms):
   * Interpolates the canvas rendering clock backward from fromTimeMs to toTimeMs,
   * causing active notes to smoothly slide UPWARD along their lanes back into place.
   */
  animateRewind(fromTimeMs, toTimeMs, durationMs = 600, onComplete = null) {
    this.isRewinding = true;
    if (this.animFrameId) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }

    const startPerf = performance.now();

    const rewindStep = (now) => {
      const elapsed = now - startPerf;
      const progress = Math.min(1.0, elapsed / durationMs);

      // Smooth easeInOutQuad easing for physical tape feel
      const eased = progress < 0.5 
        ? 2 * progress * progress 
        : 1 - Math.pow(-2 * progress + 2, 2) / 2;

      const currentRenderTime = fromTimeMs + (toTimeMs - fromTimeMs) * eased;

      // Render frame during rewind
      this.ctx.clearRect(0, 0, this.width, this.height);
      this.renderLanes();
      this.renderNotes(currentRenderTime);
      this.renderHitLine();

      if (progress < 1.0) {
        requestAnimationFrame(rewindStep);
      } else {
        this.isRewinding = false;
        if (onComplete) onComplete();
      }
    };

    requestAnimationFrame(rewindStep);
  }

  /**
   * Flawless Revive & Continue Flow:
   * 1. Plays High-Fidelity Vinyl Scratch Sample
   * 2. Computes exact 2-second target: targetTimeSec = Math.max(0, failTime - 2.0)
   * 3. Calculates complete clearance threshold: clearThresholdMs = (failTime + 1.0) * 1000
   * 4. ALL notes with timestamp_ms <= clearThresholdMs are permanently cleared / completed
   * 5. Fixes time anchor: sync.baseTimeMs = targetTimeMs, basePerfNow = performance.now()
   * 6. Applies jump directly on active player: player.seekTo(targetTimeSec, true); player.playVideo();
   * 7. Resets anti-double-miss lock and sets invulnerability window until clearThresholdMs + margin
   * 8. Executes 600ms smooth visual canvas rewind (notes slide UP) with video paused
   * 9. Resumes engine loop at 120 FPS
   */
  reviveAndResume() {
    this.synth.playAnalogTapeRewind();

    // 1. Obtener el tiempo de fallo exacto
    const player = this.sync.player;
    const currentSongTime = this.lastFailSongTimeSec || ((this.sync.getCurrentTimeMs() || 0) / 1000);
    const currentTime = (player && typeof player.getCurrentTime === 'function')
      ? (player.getCurrentTime() || currentSongTime)
      : currentSongTime;

    // 2. Punto objetivo de YouTube (rebobinar 2 segundos exactos)
    const targetTimeSec = Math.max(0, currentTime - 2.0);
    const targetTimeMs = targetTimeSec * 1000;

    // 3. Umbral de eliminación: eliminar todas las notas hasta el fallo + 1.0 segundo posterior
    const clearThresholdMs = (currentTime + 1.0) * 1000;

    // 4. CORREGIR EL ANCLAJE DEL RELOJ (Esto evita que la canción vuelva a 0)
    this.sync.baseTimeMs = targetTimeMs;
    this.sync.basePerfNow = performance.now();
    this.sync.lastPollPerfTime = this.sync.basePerfNow;
    this.sync.isPlaying = true;
    this.isPaused = false;
    this.isGameOver = false;

    // 5. Sincronizar el reproductor de YouTube: NO recargar el video, NO llamar a loadVideoById ni a startGame()
    if (player && typeof player.seekTo === 'function') {
      try {
        player.seekTo(targetTimeSec, true);
        player.playVideo();
      } catch (e) {}
    }

    // 6. Limpieza Total de Notas:
    // - Todas las notas pasadas hasta el fallo e incluso 1s posterior se marcan estrictamente como finalizadas/eliminadas
    // - Solo las notas posteriores a (currentTime + 1.0s) permanecen activas para dar margen limpio de reacción
    this.notes.forEach(note => {
      const noteTime = note.timestamp_ms || note.time || 0;
      if (noteTime <= clearThresholdMs) {
        note.hit = true;
        note.missed = false;
        note.processed = true;
        note.holding = false;
        note.holdCompleted = true;
      } else {
        note.hit = false;
        note.missed = false;
        note.processed = false;
        note.holding = false;
        note.holdCompleted = false;
      }
    });

    // 7. Limpieza de efectos y colas residuales
    this.particles.particles = [];
    this.particles.shockwaves = [];
    this.activeHolds.clear();
    this.activeTouches.clear();
    this.judgements = [];

    // 8. Resetear bloqueo contra doble fallo y asignar ventana de seguridad amplia
    this.isProcessingMiss = false;
    this.lastMissTimePerf = performance.now();
    this.invulnerableUntil = clearThresholdMs + this.latencyOffsetMs + 800;

    // 9. Trigger UI ⏪ -2.0s Rewind Badge
    if (this.ui.onShowRewindBadge) {
      this.ui.onShowRewindBadge();
    }

    // 10. Animación de Rebobinado de Notas (Visual 600ms)
    const fromRenderTime = (currentTime * 1000) + this.latencyOffsetMs;
    const toRenderTime = targetTimeMs + this.latencyOffsetMs;

    this.animateRewind(fromRenderTime, toRenderTime, 600, () => {
      this.resume();
    });
  }

  restart() {
    if (!this.beatmapData) return;
    this.loadBeatmap(this.beatmapData);
    this.sync.seekTo(0);
    this.sync.play();
  }

  stop() {
    this.isPaused = true;
    this.isRunning = false;
    this.isRewinding = false;
    this.isProcessingMiss = false;
    if (this.animFrameId) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }
    this.sync.pause();
    this.sync.clearWatchdog();
    this.activeHolds.clear();
    this.notes = [];
  }

  getLaneFromX(clientX) {
    const rect = this.canvas.getBoundingClientRect();
    const x = clientX - rect.left;
    const lane = Math.floor(x / (rect.width / 3));
    return Math.max(0, Math.min(2, lane));
  }

  handleTouchStart(e) {
    e.preventDefault();
    if (this.isPaused || this.isRewinding) return;

    const rect = this.canvas.getBoundingClientRect();
    const now = performance.now();

    for (let i = 0; i < e.changedTouches.length; i++) {
      const touch = e.changedTouches[i];
      const x = touch.clientX - rect.left;
      const y = touch.clientY - rect.top;
      const lane = this.getLaneFromX(touch.clientX);

      this.activeTouches.set(touch.identifier, {
        x0: x,
        y0: y,
        t0: now,
        lane: lane,
        swiped: false
      });

      this.triggerLaneInput(lane, 'tap', null, touch.identifier);
    }
  }

  handleTouchMove(e) {
    e.preventDefault();
    if (this.isPaused || this.isRewinding) return;

    const rect = this.canvas.getBoundingClientRect();
    const now = performance.now();

    for (let i = 0; i < e.changedTouches.length; i++) {
      const touch = e.changedTouches[i];
      const touchData = this.activeTouches.get(touch.identifier);
      if (!touchData || touchData.swiped) continue;

      const currentX = touch.clientX - rect.left;
      const currentY = touch.clientY - rect.top;
      const dx = currentX - touchData.x0;
      const dy = currentY - touchData.y0;
      const dist = Math.hypot(dx, dy);
      const elapsed = now - touchData.t0;

      if (dist > 20 && elapsed < 350) {
        let direction = 'up';
        if (Math.abs(dx) > Math.abs(dy)) {
          direction = dx > 0 ? 'right' : 'left';
        } else {
          direction = dy > 0 ? 'down' : 'up';
        }

        touchData.swiped = true;
        this.triggerLaneInput(touchData.lane, 'swipe', direction, touch.identifier);
      }
    }
  }

  handleTouchEnd(e) {
    e.preventDefault();
    for (let i = 0; i < e.changedTouches.length; i++) {
      const touch = e.changedTouches[i];
      const touchData = this.activeTouches.get(touch.identifier);
      if (touchData) {
        this.releaseLaneHold(touchData.lane, touch.identifier);
        this.activeTouches.delete(touch.identifier);
      }
    }
  }

  handleMouseDown(e) {
    if (this.isPaused || this.isRewinding) return;
    const lane = this.getLaneFromX(e.clientX);
    const rect = this.canvas.getBoundingClientRect();
    this.mouseTouch = {
      x0: e.clientX - rect.left,
      y0: e.clientY - rect.top,
      t0: performance.now(),
      lane: lane,
      swiped: false
    };
    this.triggerLaneInput(lane, 'tap', null, 'mouse');
  }

  handleMouseMove(e) {
    if (!this.mouseTouch || this.mouseTouch.swiped || this.isPaused || this.isRewinding) return;
    const rect = this.canvas.getBoundingClientRect();
    const dx = (e.clientX - rect.left) - this.mouseTouch.x0;
    const dy = (e.clientY - rect.top) - this.mouseTouch.y0;
    const dist = Math.hypot(dx, dy);

    if (dist > 20) {
      let direction = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up');
      this.mouseTouch.swiped = true;
      this.triggerLaneInput(this.mouseTouch.lane, 'swipe', direction, 'mouse');
    }
  }

  handleMouseUp() {
    if (this.mouseTouch) {
      this.releaseLaneHold(this.mouseTouch.lane, 'mouse');
      this.mouseTouch = null;
    }
  }

  triggerLaneInput(lane, inputType = 'tap', swipeDirection = null, touchId = null) {
    this.laneGlows[lane] = 1.0;
    const currentTime = this.isCalibrating 
      ? (performance.now() - this.calibrationStartTime) + this.latencyOffsetMs
      : this.sync.getCurrentTimeMs() + this.latencyOffsetMs;

    const hitX = (lane + 0.5) * this.laneWidth;
    const hitY = this.hitLineY;

    let closestNote = null;
    let minDiff = Infinity;

    for (const note of this.notes) {
      if ((!this.isCalibrating && note.lane !== lane) || note.hit || note.missed || note.holdCompleted) continue;
      const diff = Math.abs(note.timestamp_ms - currentTime);
      if (diff < 260 && diff < minDiff) {
        minDiff = diff;
        closestNote = note;
      }
    }

    // Ghost Tap Handling: tapping empty lane
    if (!closestNote) {
      if (this.isCalibrating) {
        this.synth.playClick();
        return;
      }
      
      // In active game: Ghost Tap is a real Miss! Protected with cooldown against double misses
      const nowPerf = performance.now();
      if (this.beatmapData && this.sync.isPlaying && currentTime > this.invulnerableUntil && !this.isProcessingMiss && (nowPerf - this.lastMissTimePerf >= 750)) {
        this.synth.playPunchyArcadeMiss();
        this.addJudgement('GHOST TAP', '#ff4d4d');
        this.handleMiss();
      }
      return;
    }

    if (this.isCalibrating) {
      this.judgeHit(closestNote, minDiff, hitX, hitY, 'CALIB');
      closestNote.hit = true;
      this.particles.emitHit(hitX, hitY, '#00f2fe');
      this.synth.playPianoChime();
      return;
    }

    if (closestNote.type === 'tap' && inputType === 'tap') {
      this.judgeHit(closestNote, minDiff, hitX, hitY);
      closestNote.hit = true;
      this.particles.emitHit(hitX, hitY, '#00f2fe');
    } 
    else if (closestNote.type === 'swipe' && inputType === 'swipe') {
      const targetDir = closestNote.direction || 'up';
      if (swipeDirection === targetDir || !closestNote.direction) {
        this.judgeHit(closestNote, minDiff, hitX, hitY, 'SWIPE');
        closestNote.hit = true;
        this.particles.emitSwipeBurst(hitX, hitY, targetDir, '#fee140', 36);
      }
    } 
    else if (closestNote.type === 'hold' && inputType === 'tap') {
      this.judgeHit(closestNote, minDiff, hitX, hitY);
      closestNote.holding = true;
      closestNote.missed = false;
      this.activeHolds.set(lane, {
        note: closestNote,
        touchId: touchId,
        startTime: currentTime,
        initialTime: closestNote.timestamp_ms
      });
      this.particles.emitHit(hitX, hitY, '#00ff88', 22);
    }
  }

  releaseLaneHold(lane, touchId = null) {
    const active = this.activeHolds.get(lane);
    if (!active) return;
    if (touchId !== null && active.touchId !== touchId) return;

    const currentTime = this.sync.getCurrentTimeMs() + this.latencyOffsetMs;
    const note = active.note;
    const endT = note.end_timestamp_ms || (note.timestamp_ms + (note.duration_ms || 700));

    if (currentTime >= endT - 160) {
      note.holdCompleted = true;
      note.hit = true;
      note.holding = false;
      this.addScore(450 * this.multiplier);
      const hitX = (lane + 0.5) * this.laneWidth;
      this.particles.emitHit(hitX, this.hitLineY, '#00ff88', 30);
    } else {
      note.missed = true;
      note.holding = false;
      const nowPerf = performance.now();
      if (!this.isProcessingMiss && (nowPerf - this.lastMissTimePerf >= 750)) {
        this.synth.playPunchyArcadeMiss();
        this.addJudgement('HOLD DROP', '#ff4d4d');
        this.handleMiss();
      }
    }
    this.activeHolds.delete(lane);
  }

  judgeHit(note, diffMs, x, y, customLabel = null) {
    let text = 'GREAT';
    let color = '#ffd166';
    let points = 150;

    if (diffMs <= 38) {
      text = customLabel ? `PERFECT+ ${customLabel}` : 'PERFECT+';
      color = '#00f2fe';
      points = 450;
      this.stats.perfectPlus++;
      this.streakCount++;
    } else if (diffMs <= 75) {
      text = customLabel ? `PERFECT ${customLabel}` : 'PERFECT';
      color = '#06d6a0';
      points = 300;
      this.stats.perfect++;
      this.streakCount++;
    } else {
      text = customLabel ? `GREAT ${customLabel}` : 'GREAT';
      color = '#ffd166';
      points = 150;
      this.stats.great++;
      this.streakCount = 0;
    }

    if (this.streakCount >= 15) {
      this.multiplier = 5;
    } else if (this.streakCount >= 10) {
      this.multiplier = 3;
    } else if (this.streakCount >= 5) {
      this.multiplier = 2;
    } else {
      this.multiplier = 1;
    }

    this.combo++;
    if (this.combo > this.maxCombo) this.maxCombo = this.combo;
    
    this.addScore(points * this.multiplier);
    this.addJudgement(text, color);
  }

  addScore(pts) {
    this.score += pts;
    const target90 = this.targetScore * 0.90;
    this.stars = Math.min(5, Math.floor((this.score / target90) * 5));
    this.ui.onScoreUpdate(this.score, this.combo, this.stars, this.multiplier);
  }

  handleMiss() {
    const nowPerf = performance.now();
    if (this.isProcessingMiss || (nowPerf - this.lastMissTimePerf < 750)) {
      return; // Anti-Double-Miss Cooldown Lock
    }

    this.isProcessingMiss = true;
    this.lastMissTimePerf = nowPerf;
    this.lastFailSongTimeSec = (this.sync.getCurrentTimeMs() || 0) / 1000;

    this.combo = 0;
    this.streakCount = 0;
    this.multiplier = 1;
    this.stats.miss++;
    this.ui.onScoreUpdate(this.score, this.combo, this.stars, this.multiplier);

    // Arcade penalty pause if Continue Mode is OFF
    if (!this.continueMode && !this.isCalibrating && this.beatmapData) {
      const penaltyCost = Math.pow(2, this.missCount);
      this.missCount++;
      this.pause();
      if (this.ui.onMissPenalty) {
        this.ui.onMissPenalty(penaltyCost, this.missCount);
      }
    }
  }

  addJudgement(text, color) {
    this.judgements.push({
      text: text,
      color: color,
      y: this.hitLineY - 60,
      alpha: 1.0,
      scale: 1.3,
      decay: 2.2
    });
  }

  update(dt) {
    if (this.isPaused || this.isRewinding) return;

    if (this.isCalibrating) {
      const now = performance.now();
      const currentCalibTime = (now - this.calibrationStartTime) + this.latencyOffsetMs;

      if (now >= this.nextCalibNoteTime) {
        const targetHitTime = currentCalibTime + this.scrollDurationMs;
        const audioCtx = this.synth.ensureContext();
        const delaySec = Math.max(0, (this.scrollDurationMs - this.latencyOffsetMs) / 1000);
        this.synth.playPianoChime(audioCtx.currentTime + delaySec);

        this.notes.push({
          id: this.notes.length + 1,
          lane: 1,
          type: 'tap',
          timestamp_ms: targetHitTime,
          hit: false,
          missed: false,
          flashed: false
        });

        this.nextCalibNoteTime = now + this.calibrationIntervalMs;
      }

      for (const note of this.notes) {
        if (!note.flashed && currentCalibTime >= note.timestamp_ms) {
          note.flashed = true;
          const hitX = (1 + 0.5) * this.laneWidth;
          this.laneGlows[1] = 1.0;
          this.particles.emitHit(hitX, this.hitLineY, '#00f2fe', 18);

          if (this.ui.onMetronomeBeat) {
            this.ui.onMetronomeBeat();
          }
        }
      }

      if (this.notes.length > 20) {
        this.notes.splice(0, 8);
      }

      this.updateVisualEffects(dt);
      return;
    }

    const currentTime = this.sync.getCurrentTimeMs() + this.latencyOffsetMs;
    const nowPerf = performance.now();
    const canTriggerMiss = !this.isProcessingMiss && (nowPerf - this.lastMissTimePerf >= 750);

    for (const note of this.notes) {
      if (!note.hit && !note.missed && !note.holding && !note.processed && !note.holdCompleted) {
        if (currentTime - note.timestamp_ms > 160) {
          note.missed = true;
          note.processed = true;
          if (currentTime > this.invulnerableUntil && canTriggerMiss) {
            this.synth.playPunchyArcadeMiss();
            this.addJudgement('MISS', '#ff4d4d');
            this.handleMiss();
            break; // Strictly stop evaluation to prevent double miss in the same frame
          }
        }
      }
    }

    for (const [lane, active] of this.activeHolds.entries()) {
      const note = active.note;
      const endT = note.end_timestamp_ms || (note.timestamp_ms + (note.duration_ms || 700));
      const hitX = (lane + 0.5) * this.laneWidth;
      
      this.particles.emitHoldSpark(hitX, this.hitLineY, '#00ff88');
      this.addScore(Math.round(260 * dt * this.multiplier));

      if (currentTime >= endT) {
        note.holdCompleted = true;
        note.hit = true;
        note.holding = false;
        this.activeHolds.delete(lane);
        this.particles.emitHit(hitX, this.hitLineY, '#00ff88', 35);
        this.addJudgement('HOLD CLEAR!', '#00ff88');
      }
    }

    this.updateVisualEffects(dt);

    if (this.beatmapData && this.notes.length > 0) {
      const lastNoteTime = Math.max(...this.notes.map(n => n.end_timestamp_ms || n.timestamp_ms));
      if (currentTime > lastNoteTime + 2000 && !this.isGameOver) {
        this.isGameOver = true;
        
        const diff = this.beatmapData.metadata?.difficulty || 'normal';
        let diffMultiplier = diff === 'easy' ? 1 : (diff === 'normal' ? 2 : (diff === 'hard' ? 3 : 4));
        const earnedClefs = this.stars * diffMultiplier;

        this.ui.onGameEnd(this.score, this.maxCombo, this.stars, this.stats, earnedClefs);
      }
    }
  }

  updateVisualEffects(dt) {
    for (let l = 0; l < 3; l++) {
      this.laneGlows[l] = Math.max(0, this.laneGlows[l] - dt * 4.0);
    }

    for (let i = this.judgements.length - 1; i >= 0; i--) {
      const j = this.judgements[i];
      j.alpha -= j.decay * dt;
      j.y -= 35 * dt;
      j.scale = Math.max(1.0, j.scale - dt * 1.5);
      if (j.alpha <= 0) this.judgements.splice(i, 1);
    }

    this.particles.update(dt);
  }

  render() {
    this.ctx.clearRect(0, 0, this.width, this.height);
    const currentTime = this.isCalibrating 
      ? (performance.now() - this.calibrationStartTime) + this.latencyOffsetMs
      : this.sync.getCurrentTimeMs() + this.latencyOffsetMs;

    this.renderLanes();
    this.renderNotes(currentTime);
    this.particles.render(this.ctx);
    this.renderHitLine();
    this.renderJudgements();
  }

  renderLanes() {
    const ctx = this.ctx;

    for (let l = 0; l < 3; l++) {
      const x0 = l * this.laneWidth;

      const isHolding = this.activeHolds.has(l);
      if (isHolding) {
        ctx.save();
        ctx.fillStyle = 'rgba(0, 255, 136, 0.22)';
        ctx.fillRect(x0, 0, this.laneWidth, this.height);
        ctx.restore();
      } else if (this.laneGlows[l] > 0) {
        ctx.save();
        ctx.fillStyle = `#00f2fe${Math.round(this.laneGlows[l] * 50).toString(16).padStart(2, '0')}`;
        ctx.fillRect(x0, 0, this.laneWidth, this.height);
        ctx.restore();
      }

      if (l > 0) {
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.12)';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(x0, 0);
        ctx.lineTo(x0, this.height);
        ctx.stroke();
      }
    }
  }

  renderHitLine() {
    const ctx = this.ctx;
    const y = this.hitLineY;

    ctx.save();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.85)';
    ctx.shadowColor = '#00f2fe';
    ctx.shadowBlur = 16;
    ctx.lineWidth = 3.5;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(this.width, y);
    ctx.stroke();

    for (let l = 0; l < 3; l++) {
      const cx = (l + 0.5) * this.laneWidth;
      const isHolding = this.activeHolds.has(l);
      const isPressed = this.laneGlows[l] > 0.4 || isHolding;

      ctx.beginPath();
      ctx.arc(cx, y, isHolding ? 36 : (isPressed ? 33 : 28), 0, Math.PI * 2);
      ctx.fillStyle = isHolding 
        ? 'rgba(0, 255, 136, 0.45)' 
        : (isPressed ? 'rgba(0, 242, 254, 0.35)' : 'rgba(255, 255, 255, 0.08)');
      ctx.fill();
      ctx.strokeStyle = isHolding ? '#00ff88' : (isPressed ? '#00f2fe' : 'rgba(255, 255, 255, 0.3)');
      ctx.lineWidth = isHolding ? 4 : (isPressed ? 3 : 2);
      ctx.stroke();

      if (isHolding) {
        const active = this.activeHolds.get(l);
        const startT = active.startTime;
        const endT = active.note.end_timestamp_ms || (startT + (active.note.duration_ms || 700));
        const currT = this.sync.getCurrentTimeMs() + this.latencyOffsetMs;
        const progress = Math.min(1.0, Math.max(0, (currT - startT) / (endT - startT)));

        ctx.beginPath();
        ctx.arc(cx, y, 42, -Math.PI / 2, -Math.PI / 2 + progress * Math.PI * 2);
        ctx.strokeStyle = '#00ff88';
        ctx.lineWidth = 3.5;
        ctx.stroke();
      }
    }
    ctx.restore();
  }

  // Giant Full-Lane Width Vector Chevron Drawing
  renderVectorChevron(ctx, x, y, direction, size = 32, strokeColor = '#ffffff') {
    ctx.save();
    ctx.translate(x, y);

    let angle = 0;
    if (direction === 'down') angle = Math.PI;
    else if (direction === 'left') angle = -Math.PI / 2;
    else if (direction === 'right') angle = Math.PI / 2;

    ctx.rotate(angle);

    const w = size * 1.35;
    const h = size * 0.70;
    const thickness = size * 0.38;

    // Outer Primary Bold Chevron
    ctx.beginPath();
    ctx.moveTo(0, -h);
    ctx.lineTo(w, 0);
    ctx.lineTo(w, thickness);
    ctx.lineTo(0, -h + thickness);
    ctx.lineTo(-w, thickness);
    ctx.lineTo(-w, 0);
    ctx.closePath();

    ctx.fillStyle = strokeColor;
    ctx.fill();

    // Inner Secondary Glow Chevron
    ctx.beginPath();
    ctx.moveTo(0, -h + thickness * 1.3);
    ctx.lineTo(w * 0.75, thickness * 1.3);
    ctx.lineTo(w * 0.75, thickness * 1.9);
    ctx.lineTo(0, -h + thickness * 1.9);
    ctx.lineTo(-w * 0.75, thickness * 1.9);
    ctx.lineTo(-w * 0.75, thickness * 1.3);
    ctx.closePath();

    ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
    ctx.fill();

    ctx.restore();
  }

  renderNotes(currentTime) {
    const ctx = this.ctx;

    for (const note of this.notes) {
      if (note.holdCompleted) continue;
      if (note.hit && note.type !== 'hold') continue;
      if (note.missed && !note.holding) continue;

      const isBeingHeld = note.holding && !note.holdCompleted;
      const timeUntilHit = note.timestamp_ms - currentTime;
      const x = (note.lane + 0.5) * this.laneWidth;
      const w = this.laneWidth * 0.78;
      const h = 28;

      if (note.type === 'hold') {
        const holdDuration = note.duration_ms || 700;
        const fullTailLength = (holdDuration / this.scrollDurationMs) * this.hitLineY;
        const endT = note.end_timestamp_ms || (note.timestamp_ms + holdDuration);
        
        let headY = this.hitLineY - (timeUntilHit / this.scrollDurationMs) * this.hitLineY;
        let tailLength = fullTailLength;

        if (isBeingHeld) {
          headY = this.hitLineY;
          const remainingMs = Math.max(0, endT - currentTime);
          tailLength = (remainingMs / this.scrollDurationMs) * this.hitLineY;
        }

        const endY = headY - tailLength;

        if (endY > this.height + 100 || headY < -300) continue;

        ctx.save();
        const grad = ctx.createLinearGradient(0, endY, 0, headY);
        if (isBeingHeld) {
          grad.addColorStop(0, 'rgba(0, 255, 136, 0.25)');
          grad.addColorStop(1, 'rgba(0, 255, 136, 0.95)');
          ctx.shadowColor = '#00ff88';
          ctx.shadowBlur = 22;
        } else {
          grad.addColorStop(0, 'rgba(240, 147, 251, 0.2)');
          grad.addColorStop(1, 'rgba(245, 87, 108, 0.85)');
          ctx.shadowColor = '#f5576c';
          ctx.shadowBlur = 14;
        }

        ctx.fillStyle = grad;
        ctx.fillRect(x - w * 0.4, endY, w * 0.8, tailLength);
        
        ctx.strokeStyle = isBeingHeld ? '#00ff88' : '#f5576c';
        ctx.lineWidth = isBeingHeld ? 3.5 : 2.5;
        ctx.strokeRect(x - w * 0.4, endY, w * 0.8, tailLength);

        ctx.fillStyle = '#ffffff';
        ctx.fillRect(x - w * 0.45, endY - 4, w * 0.9, 8);

        ctx.fillStyle = isBeingHeld ? '#00ff88' : '#ffffff';
        ctx.beginPath();
        ctx.roundRect(x - w / 2, headY - h / 2, w, h, 12);
        ctx.fill();

        ctx.restore();

      } else if (note.type === 'swipe') {
        // Giant Lane-Width Swipe Note (92% lane width & 58px height)
        const giantW = this.laneWidth * 0.92;
        const giantH = 58;
        const y = this.hitLineY - (timeUntilHit / this.scrollDurationMs) * this.hitLineY;
        if (y < -300 || y > this.height + 100) continue;

        ctx.save();
        const dir = note.direction || 'up';
        
        let neonGlow = '#00f2fe';
        let grad1 = '#00f2fe';
        let grad2 = '#0066ff';

        if (dir === 'up') {
          neonGlow = '#ffd700';
          grad1 = '#ffd700';
          grad2 = '#ff007f';
        } else if (dir === 'down') {
          neonGlow = '#00ff88';
          grad1 = '#00ff88';
          grad2 = '#00b4d8';
        }

        ctx.shadowColor = neonGlow;
        ctx.shadowBlur = 28;
        
        const grad = ctx.createLinearGradient(x - giantW / 2, y, x + giantW / 2, y);
        grad.addColorStop(0, grad1);
        grad.addColorStop(1, grad2);
        ctx.fillStyle = grad;

        ctx.beginPath();
        ctx.roundRect(x - giantW / 2, y - giantH / 2, giantW, giantH, 18);
        ctx.fill();

        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 3.0;
        ctx.stroke();

        this.renderVectorChevron(ctx, x, y, dir, 28, '#ffffff');

        ctx.restore();

      } else {
        const y = this.hitLineY - (timeUntilHit / this.scrollDurationMs) * this.hitLineY;
        if (y < -300 || y > this.height + 100) continue;

        ctx.save();
        ctx.shadowColor = '#00f2fe';
        ctx.shadowBlur = 14;

        const grad = ctx.createLinearGradient(x - w / 2, y, x + w / 2, y);
        grad.addColorStop(0, '#00f2fe');
        grad.addColorStop(1, '#4facfe');
        ctx.fillStyle = grad;

        ctx.beginPath();
        ctx.roundRect(x - w / 2, y - h / 2, w, h, 12);
        ctx.fill();

        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.roundRect(x - w / 4, y - h / 4, w / 2, h / 2, 6);
        ctx.fill();
        ctx.restore();
      }
    }
  }

  renderJudgements() {
    const ctx = this.ctx;
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    for (const j of this.judgements) {
      ctx.globalAlpha = Math.max(0, j.alpha);
      ctx.font = `900 ${22 * j.scale}px Outfit, sans-serif`;
      ctx.shadowColor = j.color;
      ctx.shadowBlur = 16;
      ctx.fillStyle = j.color;
      ctx.fillText(j.text, this.width / 2, j.y);
    }
    ctx.restore();
  }

  startLoop() {
    if (this.animFrameId) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }
    this.isRunning = true;
    let lastTime = performance.now();

    const loop = (now) => {
      if (!this.isRunning || this.isPaused || this.isRewinding) {
        this.animFrameId = null;
        return;
      }
      const dt = Math.min(0.05, (now - lastTime) / 1000);
      lastTime = now;

      this.update(dt);
      this.render();

      this.animFrameId = requestAnimationFrame(loop);
    };
    this.animFrameId = requestAnimationFrame(loop);
  }

  onPlayerReady() {
    console.log("YouTube Player ready.");
  }

  onPlayerStateChange(state) {
    if (state === 1) { // YT.PlayerState.PLAYING
      console.log("YouTube playback actively running.");
      
      const overlay = document.getElementById('globalLoadingOverlay');
      if (overlay) overlay.classList.remove('active');

      if (this.isInitialLaunch) {
        this.isInitialLaunch = false;
        this.invulnerableUntil = 0;
        this.isProcessingMiss = false;
        this.lastMissTimePerf = performance.now();

        if (this.ui && this.ui.onStartCountdown) {
          this.ui.onStartCountdown();
        } else {
          const curtain = document.getElementById('gameCurtain');
          if (curtain) curtain.classList.add('revealed');
        }
      } else {
        const curtain = document.getElementById('gameCurtain');
        if (curtain) curtain.classList.add('revealed');
      }
    }
  }

  onPlayerError(code, message) {
    console.error(`YouTube Player Error [${code}]:`, message);
    this.stop();
    if (this.ui && this.ui.onYouTubeError) {
      this.ui.onYouTubeError(message);
    }
  }
}
